// Design tokens and app CSS — extracted from demo-server.cjs shell() (Stage 0.4).
// Stage 0.5: single token layer + single app stylesheet — no priority overrides or legacy color aliases.
function designTokensCss() {
  return `:root{
  --font:'Manrope',ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
  --accent:#2563EB;--accent-strong:#1D4ED8;--accent-soft:rgba(37,99,235,.09);--accent-border:#BFDBFE;--accent-on-dark:#DBEAFE;
  --ink:#0B0F14;--ink-2:#475467;--ink-inverse:#FFFFFF;--line:#E6EBF0;--neutral-soft:#EEF3F8;--canvas:#F8FAFC;--surface:#FFFFFF;--sidebar:#0B0F14;--muted-on-dark:#B8C0CC;
  --warn:#B54708;--warn-soft:#FFF7ED;--warn-border:#FED7AA;--danger:#B42318;--danger-soft:#FEF2F2;--danger-border:#FECACA;--danger-on-dark:#FCA5A5;
  --ink-rgb:11,15,20;--surface-rgb:255,255,255;--canvas-rgb:248,250,252;--accent-rgb:37,99,235;--muted-rgb:71,84,103;
  --shadow-sm:0 1px 2px rgba(var(--ink-rgb),.05);--shadow-md:0 12px 32px rgba(var(--ink-rgb),.07);--radius-card:16px;
  --type-display:28px;--type-title:22px;--type-heading:18px;--type-body:15px;--type-small:13px;--type-label:11px;

}`;
}


