const STAGE1_QUALITY_CSS = `
.stage1-quality{display:grid;gap:16px;border:1px solid var(--line);border-radius:18px;background:var(--surface);box-shadow:var(--shadow-sm);padding:20px}
.stage1-quality-head{display:flex;align-items:flex-start;justify-content:space-between;gap:20px}
.stage1-quality-head h2{margin:4px 0 2px;color:var(--ink);font-size:22px;line-height:28px}
.stage1-quality-head p{margin:0;color:var(--ink-2);font-size:13px}
.stage1-quality-action{display:flex;align-items:center;justify-content:flex-end;gap:10px;flex-wrap:wrap}
.stage1-quality-action form{margin:0}
.stage1-quality-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--line);border-radius:14px;overflow:hidden}
.stage1-quality-grid article{display:grid;align-content:start;min-height:112px;padding:15px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);background:var(--surface)}
.stage1-quality-grid article:nth-child(4n){border-right:0}
.stage1-quality-grid article:nth-last-child(-n+4){border-bottom:0}
.stage1-quality-grid article>span{color:var(--accent-strong);font-size:10px;line-height:14px;font-weight:700;text-transform:uppercase;letter-spacing:.08em}
.stage1-quality-grid article>strong{margin-top:5px;color:var(--ink);font-size:28px;line-height:34px;font-weight:750;letter-spacing:-.03em}
.stage1-quality-grid article>small{display:block;margin-top:3px;color:var(--ink-2);font-size:11px;line-height:16px;overflow-wrap:anywhere}
.stage1-progress{height:8px;overflow:hidden;border-radius:999px;background:var(--line)}
.stage1-progress span{display:block;height:100%;border-radius:inherit;background:var(--accent);transition:width .25s ease}
.stage1-progress-copy,.stage1-reconcile{margin:0;color:var(--ink-2);font-size:12px;line-height:18px}
.stage1-reconcile{padding-top:2px}
.stage1-quality>.notice{margin:0}
@media(max-width:1180px){.stage1-quality-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.stage1-quality-grid article:nth-child(4n){border-right:1px solid var(--line)}.stage1-quality-grid article:nth-child(2n){border-right:0}.stage1-quality-grid article:nth-last-child(-n+4){border-bottom:1px solid var(--line)}.stage1-quality-grid article:nth-last-child(-n+2){border-bottom:0}}
@media(max-width:680px){.stage1-quality-head{display:grid}.stage1-quality-action{justify-content:flex-start}.stage1-quality-grid{grid-template-columns:1fr}.stage1-quality-grid article,.stage1-quality-grid article:nth-child(2n),.stage1-quality-grid article:nth-child(4n){border-right:0;border-bottom:1px solid var(--line)}.stage1-quality-grid article:last-child{border-bottom:0}}
`;

